<?php require '../includes/auth.php';require_role('admin');$orders=db()->query('SELECT o.*,u.name buyer_name FROM orders o JOIN users u ON u.id=o.buyer_id ORDER BY o.created_at DESC')->fetchAll();$pageTitle='All orders';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>All marketplace orders</h1></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Buyer</th><th>Placed</th><th>Payment</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e($o['order_number'])?></td><td><?=e($o['buyer_name'])?></td><td><?=date('d M Y H:i',strtotime($o['created_at']))?></td><td><?=e($o['payment_method'])?><br><span class="badge <?=e($o['payment_status'])?>"><?=e(ucfirst($o['payment_status']))?></span></td><td><span class="badge <?=status_class($o['status'])?>"><?=e($o['status'])?></span></td><td>₹<?=number_format($o['total'],2)?></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/footer.php'; ?>
